from collections import Counter

def maxScoreWords(words, letters, score):
    def score_word(word, score_map):
        return sum(score_map[char] for char in word)

    def backtrack(index, remaining_letters, current_score):
        if index == len(words):
            return current_score

        skip_current = backtrack(index + 1, remaining_letters, current_score)

        word_counter = Counter(words[index])
        if all(remaining_letters[char] >= word_counter[char] for char in word_counter):
            for char in word_counter:
                remaining_letters[char] -= word_counter[char]
            take_current = backtrack(index + 1, remaining_letters, current_score + score_word(words[index], score_map))
            for char in word_counter:
                remaining_letters[char] += word_counter[char]
            return max(skip_current, take_current)
        else:
            return skip_current

    score_map = {chr(i + ord('a')): score[i] for i in range(26)}
    letter_counter = Counter(letters)
    return backtrack(0, letter_counter, 0)
